from pathlib import Path
import sys
root=Path(sys.argv[1]); app=root/'public'/'app.js'; cssp=root/'public'/'styles.css'; a=app.read_text(); css=cssp.read_text()
def bounds(name):
 s=[a.find(f'function {name}('),a.find(f'async function {name}(')];s=[x for x in s if x>=0]
 if not s: raise SystemExit('Função não encontrada: '+name)
 p=min(s);q=min([x for x in [a.find('\nfunction ',p+1),a.find('\nasync function ',p+1)] if x>=0] or [len(a)]);return p,q
def fn(name,code):
 global a;p,q=bounds(name);a=a[:p]+code+a[q:]
def rep(old,new,label):
 global a
 if old not in a: raise SystemExit('Trecho não encontrado: '+label)
 a=a.replace(old,new,1)
fn('scopeSwitcher',r'''function scopeSwitcher(){if(!sharedActive()||!['home','income','expenses','debts','goals','calendar','insights'].includes(state.page))return '';const partner=state.data.sharing.partner?.name||'parceiro',shared=state.data.scope==='shared';return `<div class="scope-bar smart-scope-bar"><div class="scope-copy"><span>${shared?ic('users',15):ic('user',15)}</span><div><strong>${shared?'Do casal':'Pessoal'}</strong><small>${shared?`Contas em comum com ${esc(partner)}`:'Suas despesas e planos continuam privados'}</small></div></div><div class="scope-seg"><button type="button" data-scope="personal" class="${!shared?'active':''}">Pessoal</button><button type="button" data-scope="shared" class="${shared?'active':''}">Casal</button></div></div>`}''')
fn('sharingPage',r'''function sharingPage(){const sh=state.data.sharing||{},me=state.data.profile;if(sh.active){const partner=sh.partner||{},shared=state.data.scope==='shared';return `${head('Compartilhamento','O pessoal continua privado. O que é do casal fica organizado entre vocês.')}<div class="sharing-hero panel sharing-hero-smart"><div class="couple-avatars"><span>${initials(me.name)}</span><i>${ic('users',18)}</i><span>${initials(partner.name)}</span></div><div><span class="eyebrow">RITMO A DOIS</span><h2>${esc(me.name.split(' ')[0])} & ${esc((partner.name||'Parceiro').split(' ')[0])}</h2><p>Dois espaços dentro do mesmo Ritmo. Nenhuma despesa pessoal é mostrada ao parceiro automaticamente.</p></div></div><div class="couple-space-grid"><article class="couple-space-card ${!shared?'active':''}"><span class="couple-space-icon personal">${ic('user',22)}</span><div><span class="eyebrow">SÓ SEU</span><h3>Pessoal</h3><p>Compras, compromissos, dívidas e metas que dizem respeito somente a você.</p></div><button class="btn btn-secondary" data-scope="personal">Abrir meu espaço</button></article><article class="couple-space-card ${shared?'active':''}"><span class="couple-space-icon">${ic('users',22)}</span><div><span class="eyebrow">EM COMUM</span><h3>Do casal</h3><p>Aluguel, água, luz, mercado, dívidas e objetivos administrados pelos dois.</p></div><button class="btn btn-primary" data-scope="shared">Abrir espaço do casal</button></article></div><div class="panel couple-quick-panel"><div class="panel-title"><div><h3>Adicionar rapidamente</h3><small>Já abre no espaço certo.</small></div></div><div class="couple-quick-grid"><button type="button" data-smart-new="expense" data-new-scope="shared"><span>${ic('home',18)}</span><strong>Conta da casa</strong><small>Do casal</small></button><button type="button" data-smart-new="debt" data-new-scope="shared"><span>${ic('wallet',18)}</span><strong>Dívida em comum</strong><small>Do casal</small></button><button type="button" data-smart-new="goal" data-new-scope="shared"><span>${ic('target',18)}</span><strong>Meta juntos</strong><small>Do casal</small></button><button type="button" data-smart-new="expense" data-new-scope="personal"><span>${ic('user',18)}</span><strong>Despesa pessoal</strong><small>Só você vê</small></button></div></div><div class="couple-privacy-note">${ic('shield',16)} <span><strong>Individualidade preservada.</strong> Só os itens marcados como <b>Do casal</b> aparecem para os dois.</span></div>`}const incoming=sh.incoming_invites||[],outgoing=sh.outgoing_invites||[];return `${head('Compartilhamento','Conecte duas contas sem dividir senha ou misturar despesas pessoais.')}<div class="sharing-grid setup"><div class="panel share-setup-card"><span class="sharing-big-icon">${ic('users',28)}</span><h2>Organização a dois</h2><p>Depois da conexão, cada lançamento poderá ser marcado como <strong>Pessoal</strong> ou <strong>Do casal</strong>.</p><form id="shareInviteForm"><label class="field">Usuário do parceiro<input name="username" autocomplete="off" placeholder="Ex.: maria.silva" required minlength="3"></label><button class="btn btn-primary" type="submit">Criar convite</button></form></div><div class="panel"><div class="panel-title"><div><h3>Tenho um código</h3><small>Use o código recebido do seu parceiro.</small></div></div><form id="shareCodeForm" class="share-code-form"><input name="code" maxlength="10" placeholder="CÓDIGO" autocomplete="off" required><button class="btn btn-secondary" type="submit">Conectar</button></form></div></div>${incoming.length?`<section class="share-list"><h3>Convites recebidos</h3>${incoming.map(i=>`<article class="share-invite"><span class="mini-avatar">${initials(i.inviter_name)}</span><div><strong>${esc(i.inviter_name)}</strong><small>@${esc(i.inviter_username)} quer criar um espaço do casal com você.</small></div><div class="invite-actions"><button class="btn btn-primary" data-share-accept="${i.id}">Aceitar</button><button class="mini-btn" data-share-decline="${i.id}">Recusar</button></div></article>`).join('')}</section>`:''}${outgoing.length?`<section class="share-list"><h3>Convite enviado</h3>${outgoing.map(i=>`<article class="share-invite code"><span class="mini-avatar">${initials(i.invitee_name)}</span><div><strong>${esc(i.invitee_name)}</strong><small>@${esc(i.invitee_username)} • válido por 7 dias</small><button class="invite-code" data-copy-code="${esc(i.code)}">${esc(i.code)} ⧉</button></div><button class="mini-btn" data-share-cancel="${i.id}">Cancelar</button></article>`).join('')}</section>`:''}`}''')
fn('modalHtml',r'''function financeScopeField(m){const selected=m.forcedScope||state.data.scope||'personal';if(!sharedActive())return '<input type="hidden" name="financial_scope" value="personal">';if(m.item)return `<div class="finance-scope-readonly full"><span>${m.item?.shared?ic('users',16):ic('user',16)}</span><div><strong>${m.item?.shared?'Do casal':'Pessoal'}</strong><small>O espaço não muda durante a edição.</small></div></div>`;return `<div class="finance-scope-field full"><span class="finance-scope-label">Este lançamento pertence a</span><div class="finance-scope-segment"><button type="button" data-finance-scope-value="personal" class="${selected==='personal'?'active':''}">${ic('user',15)} Pessoal</button><button type="button" data-finance-scope-value="shared" class="${selected==='shared'?'active':''}">${ic('users',15)} Do casal</button></div><input type="hidden" name="financial_scope" value="${selected}"><small class="finance-scope-help">${selected==='shared'?'Os dois poderão ver e administrar este item.':'Somente você verá este item.'}</small></div>`}
function modalHtml(){const m=state.modal;if(m.type==='filter')return filterModalHtml(m.filterType);if(m.type==='quick')return `<div class="modal-wrap" id="modalWrap"><div class="modal"><div class="modal-head"><h3>Ação rápida</h3><button class="close" id="modalClose">×</button></div><div class="quick-grid">${[['income','Nova entrada','up'],['expense','Nova saída','down'],['debt','Nova dívida','wallet'],['goal','Nova meta','target']].map(x=>`<button class="quick-card" data-new="${x[0]}"><span class="setting-icon">${ic(x[2],18)}</span><strong>${x[1]}</strong></button>`).join('')}</div></div></div>`;const {type,item}=m;let title='',fields='';if(type==='income'){title=item?'Editar entrada':'Nova entrada';fields=`${financeScopeField(m)}${input('description','Descrição',item?.description,'Ex.: Salário')}${moneyInput('amount','Valor',item?.amount)}${select('category','Categoria',['Salário','Renda extra','Venda','Reembolso','Outros'],item?.category)}${dateInput('date','Data',item?.date||isoToday())}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='expense'){title=item?'Editar saída':'Nova saída';fields=`${financeScopeField(m)}${input('description','Descrição',item?.description,'Ex.: Aluguel')}${moneyInput('amount','Valor',item?.amount)}${select('category','Categoria',['Moradia','Contas da casa','Supermercado','Alimentação','Transporte','Saúde','Lazer','Educação','Filhos','Assinaturas','Dívidas','Outros'],item?.category)}${select('status','Status',['pendente','pago'],item?.status||'pendente')}${dateInput('date','Data',item?.date||isoToday())}${dateInput('due_date','Vencimento',item?.due_date||'')}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='debt'){title=item?'Editar dívida':'Nova dívida';fields=`${financeScopeField(m)}${input('creditor','Dívida / credor',item?.creditor,'Ex.: Cartão ou empréstimo')}${moneyInput('total_amount','Valor total',item?.total_amount)}${dateInput('start_date','Data inicial',item?.start_date||isoToday())}${dateInput('due_date','Vencimento',item?.due_date||'')}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='goal'){title=item?'Editar meta':'Nova meta';fields=`${financeScopeField(m)}${input('name','Nome da meta',item?.name,'Ex.: Viagem')}${moneyInput('target_amount','Valor alvo',item?.target_amount)}${select('category','Categoria',['Viagem','Carro','Casa','Estudos','Reserva de emergência','Personalizado'],item?.category)}${dateInput('deadline','Prazo',item?.deadline||'')}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='payment'||type==='credit'){const d=state.data.debts.find(x=>x.id===m.debtId);title=type==='payment'?'Registrar pagamento':'Registrar haver';fields=`<div class="full" style="font-size:11px;color:var(--muted);margin-bottom:8px">Saldo atual: <strong>${money(debtCurrentBalance(d||{}))}</strong></div>${moneyInput('amount',type==='payment'?'Valor pago':'Valor do haver')}${dateInput('date','Data',isoToday())}${input('notes','Observação','','Opcional','full')}${type==='credit'?`<label class="field full" style="display:flex;align-items:center;gap:8px"><input name="cash_received" type="checkbox" style="width:auto;margin:0"> Haver recebido em dinheiro (gera uma entrada)</label>`:''}`}
if(type==='contribution'){const g=state.data.goals.find(x=>x.id===m.goalId);title='Adicionar à meta';fields=`<div class="full contribution-context"><small>${esc(g?.name||'Meta')}</small><strong>${money(g?.current_amount)} de ${money(g?.target_amount)}</strong></div>${moneyInput('amount','Valor')}${dateInput('date','Data',isoToday())}${input('notes','Observação','','Opcional','full')}`}
return `<div class="modal-wrap action-sheet-wrap" id="modalWrap"><form class="modal action-sheet" id="dataForm"><div class="modal-grabber" aria-hidden="true"></div><div class="modal-head"><h3>${title}</h3><button class="close" type="button" id="modalClose">×</button></div><div class="form-grid action-sheet-body">${fields}</div><div class="modal-save-bar"><button class="btn btn-primary" type="submit">Salvar</button></div></form></div>`}''')
fn('submitData',r'''async function submitData(e){e.preventDefault();const f=new FormData(e.currentTarget),o=Object.fromEntries(f.entries()),m=state.modal;for(const k of ['amount','total_amount','target_amount'])if(k in o)o[k]=Number(o[k]);if(m.type==='credit')o.cash_received=f.get('cash_received')==='on';if(m.type==='expense'&&o.status==='pago'&&o.date>financeToday())return toast('Uma saída futura deve ficar como Pendente até o pagamento acontecer.');if(['payment','credit','contribution'].includes(m.type)&&o.date>financeToday())return toast('Registre esta ação somente quando ela realmente acontecer.');let targetScope=state.data.scope;if(['income','expense','debt','goal'].includes(m.type)&&!m.item){const chosen=o.financial_scope||m.forcedScope||state.data.scope;targetScope=sharedActive()&&chosen==='shared'?'shared':'personal'}delete o.financial_scope;delete o.goal_scope;const prefix=scopePrefix(targetScope);let path='',method='POST';if(['income','expense','debt','goal'].includes(m.type)){const plural={income:'incomes',expense:'expenses',debt:'debts',goal:'goals'}[m.type];path=`${prefix}/${plural}${m.item?`/${m.item.id}`:''}`;method=m.item?'PATCH':'POST'}else if(m.type==='payment')path=`${scopePrefix()}/debts/${m.debtId}/payment`;else if(m.type==='credit')path=`${scopePrefix()}/debts/${m.debtId}/credit`;else if(m.type==='contribution')path=`${scopePrefix()}/goals/${m.goalId}/contributions`;try{await api(path,{method,body:JSON.stringify(o)});state.data=await api('/api/bootstrap');state.modal=null;if(m.returnPage)state.page=m.returnPage;renderApp(false);toast(['income','expense','debt','goal'].includes(m.type)&&!m.item?`Salvo em ${targetScope==='shared'?'Do casal':'Pessoal'}.`:'Atualizado com sucesso.')}catch(err){toast(err.message)}}''')
rep("$$('[data-new]').forEach(b=>b.onclick=()=>{state.modal={type:b.dataset.new};renderApp(false)});","$$('[data-new]').forEach(b=>b.onclick=()=>{state.modal={type:b.dataset.new};renderApp(false)});$$('[data-smart-new]').forEach(b=>b.onclick=()=>{state.modal={type:b.dataset.smartNew,forcedScope:b.dataset.newScope,returnPage:'sharing'};renderApp(false)});$$('[data-finance-scope-value]').forEach(b=>b.onclick=()=>{const wrap=b.closest('.finance-scope-field'),input=wrap?.querySelector('input[name=\"financial_scope\"]'),help=wrap?.querySelector('.finance-scope-help');if(!input)return;input.value=b.dataset.financeScopeValue;wrap.querySelectorAll('[data-finance-scope-value]').forEach(x=>x.classList.toggle('active',x===b));if(help)help.textContent=input.value==='shared'?'Os dois poderão ver e administrar este item.':'Somente você verá este item.'});",'bindings casal')
app.write_text(a)
css+=r'''
.smart-scope-bar .scope-seg{min-width:154px}.sharing-hero-smart{display:flex;align-items:center;gap:18px}.sharing-hero-smart p{margin:0;color:var(--muted);line-height:1.5}.couple-space-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0}.couple-space-card{border:1px solid var(--line);background:var(--surface-solid);border-radius:20px;padding:16px;display:grid;grid-template-columns:44px 1fr;gap:12px}.couple-space-card.active{border-color:color-mix(in srgb,var(--primary) 34%,var(--line))}.couple-space-card .btn{grid-column:1/-1}.couple-space-card h3{margin:3px 0 4px}.couple-space-card p{margin:0;color:var(--muted);font-size:10px}.couple-space-icon{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:color-mix(in srgb,var(--sage) 14%,var(--surface2));color:var(--sage)}.couple-space-icon.personal{color:var(--primary)}.couple-quick-panel{margin-top:12px}.couple-quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.couple-quick-grid button{border:1px solid var(--line);background:var(--surface2);border-radius:15px;padding:11px 8px;display:flex;flex-direction:column;align-items:flex-start;gap:4px;text-align:left}.couple-quick-grid strong{font-size:10px}.couple-quick-grid small{font-size:8px;color:var(--muted)}.couple-privacy-note{margin-top:12px;padding:12px 14px;border-radius:16px;background:color-mix(in srgb,var(--sage) 8%,var(--surface-solid));display:flex;gap:10px;color:var(--muted);font-size:9.5px}.finance-scope-field{border-radius:16px;background:var(--surface2);padding:11px}.finance-scope-label{display:block;font-size:9px;font-weight:800;color:var(--muted);margin-bottom:8px}.finance-scope-segment{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:3px;border-radius:12px;background:rgba(0,0,0,.04)}.finance-scope-segment button{border:0;background:transparent;border-radius:10px;min-height:38px;font-size:10px;font-weight:750;color:var(--muted)}.finance-scope-segment button.active{background:var(--surface-solid);color:var(--primary);box-shadow:0 2px 8px rgba(0,0,0,.07)}.finance-scope-help{display:block;margin-top:7px;font-size:8.5px;color:var(--muted);text-align:center}.finance-scope-readonly,.contribution-context{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:14px;background:var(--surface2)}
@media(max-width:760px){.sharing-hero-smart{align-items:flex-start}.couple-space-grid{grid-template-columns:1fr}.couple-quick-grid{grid-template-columns:1fr 1fr}}
''';cssp.write_text(css)
